const icalText = $input.first().json.data || '';

if (!icalText) {
  return [];
}

// Dedup: use workflow static data to track processed UID+DTSTART combos
const staticData = $getWorkflowStaticData('global');
if (!staticData.processedCalendarUids) {
  staticData.processedCalendarUids = {};
}

// TTL cleanup: remove entries older than 48 hours
const ttlMs = 48 * 60 * 60 * 1000;
const nowMs = Date.now();
for (const key of Object.keys(staticData.processedCalendarUids)) {
  const ts = new Date(staticData.processedCalendarUids[key]).getTime();
  if (nowMs - ts > ttlMs) {
    delete staticData.processedCalendarUids[key];
  }
}

// Parse VEVENT blocks from iCal text
const eventBlocks = icalText.split('BEGIN:VEVENT').slice(1);
const now = new Date();
const windowMs = 5 * 60 * 1000; // 5 minutes

const dueEvents = [];

for (const block of eventBlocks) {
  const getField = (name) => {
    const match = block.match(new RegExp(`^${name}[^:]*:(.+)$`, 'm'));
    return match ? match[1].trim() : null;
  };

  const uid = getField('UID');
  const summary = getField('SUMMARY');
  const description = getField('DESCRIPTION') || '';
  const dtstart = getField('DTSTART');
  const status = getField('STATUS') || 'CONFIRMED';

  // Only process events with hp:propose in description
  if (!description.includes('hp:propose')) continue;

  // Only process confirmed (not cancelled) events
  if (status === 'CANCELLED') continue;

  if (!dtstart) continue;

  // Parse datetime (basic iCal datetime: YYYYMMDDTHHmmssZ or YYYYMMDDTHHmmss)
  let eventTime;
  try {
    const d = dtstart.replace('Z', '');
    eventTime = new Date(
      `${d.slice(0,4)}-${d.slice(4,6)}-${d.slice(6,8)}T${d.slice(9,11)}:${d.slice(11,13)}:${d.slice(13,15)}${dtstart.endsWith('Z') ? 'Z' : ''}`
    );
  } catch (e) {
    continue;
  }

  // Dedup: skip if this UID+DTSTART was already processed
  const dedupKey = `${uid}::${dtstart}`;
  if (staticData.processedCalendarUids[dedupKey]) continue;

  // Fire if event is within the next poll window (or overdue by up to 5 min)
  const diffMs = eventTime - now;
  if (diffMs >= -windowMs && diffMs <= windowMs) {
    const intentMatch = description.match(/hp:propose\s+(.+?)(?:\n|$)/i);
    const intent = intentMatch ? intentMatch[1].trim() : summary;

    // Mark as processed before proposing
    staticData.processedCalendarUids[dedupKey] = eventTime.toISOString();

    dueEvents.push({
      uid,
      summary,
      description,
      intent,
      dtstart,
      eventTime: eventTime.toISOString()
    });
  }
}

if (dueEvents.length === 0) {
  return [];
}

return dueEvents.map(e => ({ json: e }));
